/*
 * wavetables.h
 *
 * Tables for the wavetable lfo oscillator mode, generated by tools/gen_wavetables.py
 */

#ifndef WAVETABLES_H_
#define WAVETABLES_H_

#include <stdint.h>

#define WT_WAVES  8
#define WT_LEVELS 7
//level k has 1<<wavetable_level_bits[k] samples, plus one extra, so interpolation needs no wrap
#ifndef WT_WAVE_SIZE
#define WT_WAVE_SIZE 2567
#endif

//level k is for fundamentals up to 156.25 Hz * 2^k. phase increment @48 kHz of 156.25 Hz:
#define WT_LEVEL0_INC 13981013u

extern const uint16_t wavetable_level_offset[WT_LEVELS];
extern const uint8_t wavetable_level_bits[WT_LEVELS];
extern const int16_t wavetable[WT_WAVES][WT_WAVE_SIZE];

#endif /* WAVETABLES_H_ */
